Future<List<SessionRecord>> sessionRecords(String id) async {
  final path = manager[id]!.sessionId;
  final storage = await JsonlSessionStorage.open(env, path);
  return storage.getEntries();
}

/// Waits out the UNAWAITED final transcript flush (pins append right
/// after the persisted messages, in the same chained flush) and returns
/// the settled records.
Future<List<SessionRecord>> settledRecords(String id) async {
  final placeholder = '${manager.parentSessionId}/$id';
  for (var i = 0; i < 2000; i++) {
    if (manager[id]!.sessionId == placeholder) {
      await Future<void>.delayed(const Duration(milliseconds: 1));
      continue;
    }
    final records = await sessionRecords(id);
    final settled = _isFlushSettled(records);
    if (settled) return records;
    await Future<void>.delayed(const Duration(milliseconds: 2));
  }
  fail('child "$id" flush never settled');
}

/// Settled = the last record is a message (a pin record trailing a
/// flush means the pin writes may still be in flight).
static bool _isFlushSettled(List<SessionRecord> records) {
  if (records.isEmpty) return true;
  return records.last is! SegmentPinRecord;
}

