  required int window,
  required bool hasWorkingSet,
  bool estimated = true,
}) {
  if (window <= 0) return '';
  final mark = estimated ? estimateMark : '';
  final tail = hasWorkingSet
      ? 'your working set is pinned — continue'
      : 'no working set yet — write one now with working_set(text), '
